"""Chinese E0/E1/E2 report, provenance and failure-inclusive acceptance checks."""
from pathlib import Path
import sys,json,hashlib,platform
from datetime import datetime,timezone
import numpy as np
import pandas as pd
import yaml
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'outputs/self_reference_seed_diagnosis'

def md(df):
    def cell(x):
        if pd.isna(x):return 'N/A'
        return f'{x:.5f}' if isinstance(x,(float,np.floating)) else str(x).replace('|','/')
    return '| '+' | '.join(df.columns)+' |\n| '+' | '.join(['---']*len(df.columns))+' |\n'+'\n'.join('| '+' | '.join(cell(x) for x in row)+' |' for row in df.itertuples(index=False,name=None))

def main():
    cfg=yaml.safe_load((OUT/'configs/resolved.yaml').read_text());s=pd.read_csv(OUT/'seed_summary.csv');p=pd.read_csv(OUT/'seed_metrics_per_image.csv');t=pd.read_csv(OUT/'token_reliability_summary.csv');f=pd.read_csv(OUT/'memory_feasibility.csv');r=pd.read_csv(OUT/'self_reference_summary.csv');pair=pd.read_csv(OUT/'self_matching_paired_comparison.csv');exp=pd.read_csv(OUT/'seed_expansion_summary.csv');objects=pd.read_csv(OUT/'object_seed_coverage_summary.csv');lum=pd.read_csv(OUT/'lumen_gt_diagnostic.csv');gate=pd.read_csv(OUT/'positive_stroma_gate_audit.csv');rule=pd.read_csv(OUT/'morphology_rule_rejections.csv')
    for cls in ['fg','bg']:
        f[cls+'_memory_status']=np.where(f[cls+'_memory']==0,'EMPTY_MEMORY',np.where(f[cls+'_memory']<50,'INSUFFICIENT_MEMORY','VALID'))
    f.to_csv(OUT/'memory_feasibility.csv',index=False)
    # Instance/object uncertainty and GT-assisted label relation are kept separate from generation.
    lumen=[]
    for ds,sub in lum.groupby('dataset'):
        total=sub.candidate_pixels.sum();lumen.append({'dataset':ds,'rgb_lumen_candidate_pixels':int(total),'candidate_gt_fg_fraction':sub.candidate_gt_fg_pixels.sum()/total if total else None,'images_with_candidate':int((sub.candidate_pixels>0).sum())})
    lines=['# E0 — Training-Free Self-Reference Seed Reliability Diagnosis','','## 1. Motivation','','Self-reference需要可靠且同时可用的两类参考，而不是把不确定像素强制补成完整分割。本文完整报告Seed精度、覆盖率、空缺及Top50可执行率，不能把高精度的极少Seed或成功执行的子集当作全测试集成功。', '', '## 2. Experimental Setup','','GLaS Test A+B 80张、CRAG官方Test 40张；A/B/C全部执行，每图自身RGB独立生成，不读训练图像或外部标注Support。首先完成全部120张Seed生成，才加载GT评价；E1先固定候选/抽样并保存Memory，再加载GT oracle；E2先推理，再加载GT。全部阈值与扰动在任何GT评价前冻结于configs/self_reference_e0.yaml及configs/protocol_E0.json，后续没有依据Dice或Seed精度改规则。', '', '特征在完整native图像上计算，无整体Mask缩放假充Token对齐。RGB→Lab，固定HED混合矩阵[[0.65,0.70,0.29],[0.07,0.99,0.11],[0.27,0.57,0.78]]，与本地skimage.color.colorconv.rgb_from_hed相同；OD使用−log(max(RGB/255,1e−6))，HED为log RGB/log(1e−6)乘逆矩阵后截断非负。H/E各自在该图tissue内按2/98百分位归一化并截到[0,1]；无GT归一化。记录矩阵是固定颜色反卷积，不声称真实染料浓度或跨扫描仪精确分离。局部纹理为9×9反射窗口灰度标准差。', '', 'SLIC目标1024px/区域（16–2500区域）、compactness10、sigma1、10次迭代；区域特征为mean Lab/H/E/gray/local texture、log area、归一化质心，固定权重后K-means K=5，seed2026、10次初始化。5类仅是外观类，类别编号不赋语义。旧sklearn中同一Lloyd算法名为full，兼容代码按版本选择full/lloyd；没有改变聚类目标。', '', '**A：**外观密集带closing→hole filling→封闭/面积proposal→腐蚀；BG必须同时有E-rich/H-poor/低纹理区域证据，不能用NOT FG。**B：**独立检查hole面积、边界、长宽比、包围度、wall/interior H差及相邻区域，再区分epithelial与interior，排除RGB lumen candidate；BG另需更强外观及邻接一致性。A没有上皮/内部语义分支，A的combined-only tokens只是basic proposal来源。**C：**对原B与hflip、vflip、rot90及固定亮度/颜色扰动的独立B输出取类别交集，逆变换回native；原Ignore从不升级。亮度gain1.03、RGB gains[1.01,0.99,1.0]。以上为自定义确定性heuristic，不声称复现GlandSAM。', '', 'UNI完全复用既有ViT-L/16 cache（SHA56ef09b44a25dc5c7eedc55551b3d47bcd17659a7a33837cf9abc9ec4e2ffb40）；RGB字节、448/224、offset0/8、float32 encoder、float16 tokens构成的cache key及窗口坐标逐图验证。没有重新提取UNI，也没有网络训练/微调。Memory严格来自本图三值Seed occupancy：r_fg≥0.9且r_bg=0或对称规则，合并0/8后每类最多512，global PCG64 seed2026、FG先BG。无fallback，无复制，无GT补足。', '', 'S0复用原SegmentationPipeline、SimilarityRetriever及Margin fp16→28→448 bilinear→window/offset mean→256 bilinear→>0。S1仅增加原图物理center距离≤32px的排除；重叠窗口相同center及offset邻域、反射Padding的center映回原图均处理。若任一Query Token任一类可用邻居不足50，整图该模式无效；不退回S0。', '', '12项单元/合成/回归检查通过：含三值与空Precision、Ignore不进Memory、native窗口/offset/reflection、重复位置center、空间排除和固定K、RGB cache错误指纹拒绝、无GT seed调用路径、合成E0→E1→E2空Memory及resume。E0源代码版本与后续恢复检查版本分别记录，阶段间只增强checkpoint/provenance，没有改变Seed规则。','','## 3. Seed Precision–Coverage Trade-off','',md(s[['dataset','generator','images','macro_fg_precision','macro_bg_precision','macro_fg_coverage','macro_bg_coverage','macro_ignore_ratio','macro_tissue_ignore_ratio','macro_fg_nonempty','macro_bg_nonempty']]),'', 'Precision分母为0记N/A，Macro只平均非空图并明确分母；Coverage在GT类别存在时空Seed为0；空生成率不能被N/A平均掩盖。以下Pooled按像素计数，不能与Macro混用：','',md(s[['dataset','generator','fg_precision_valid_images','bg_precision_valid_images','pooled_fg_precision','pooled_bg_precision','pooled_fg_coverage','pooled_bg_coverage','pooled_ignore_ratio','pooled_tissue_ignore_ratio','pooled_object_seed_coverage_native','pooled_object_seed_coverage_256']]),'', 'GT对象为二值GT的8连通区域，并非原始instance ID。256尺度过滤面积<50；native阈值按50×H×W/65536取整，small/medium/large界限对应256面积200/1000按比例缩放。两个尺度连通拓扑可能因NN缩放不同；分别报告。至少1个FG Seed像素命中即算seeded，不能把该指标当作完整分割。','',md(objects),'', '腺腔标签核对只用于事后解释：二值GT/instance覆盖范围并无独立lumen类别；固定first/middle/last RGB与GT叠图见lumen_definition_audit。RGB-derived candidate不是经解剖核实的腔，可能含组织裂隙。其与GT关系如下，不能据此把所有填洞自动当FG。生成中该candidate始终不加入FG。','',md(pd.DataFrame(lumen)),'','## 4. Token-level Reliability','',md(t[['dataset','generator','images','valid_memories','valid_rate','empty_memories','insufficient_memories','macro_token_coverage','fg_tokens_median','bg_tokens_median','fg_zero_images','bg_zero_images','fg_one_to49_images','bg_one_to49_images']]),'',md(t[['dataset','generator','fg_tokens_total','bg_tokens_total','fg_pooled_gt_mean_purity','bg_pooled_gt_mean_purity','fg_pooled_gt_strict_purity','bg_pooled_gt_strict_purity']]),'', 'Purity为真实GT占据的平均比例，strict purity为真实GT正确类occupancy≥0.9的Token比例，contamination=1−mean purity。均为GT-assisted diagnostic，不参与候选或抽样。候选Token按窗口重复计数，非独立组织样本。Ignore从不作为第三类bank或补缺类别；跨epithelial/interior组合满足0.9的Token单独计combined-only。逐图数量及分支统计在token_reliability.csv。','','## 5. Self-Reference Retrieval','',md(r),'', 'valid_only指标仅代表明确数量检查通过的图像，不能代表80/40张全测试集。所有失败均保留在self_reference_per_image.csv及failure_cases.csv。比较自匹配影响必须在S0/S1共同有效子集上进行：','',md(pair.drop(columns=['paired_image_ids'])),'', '未配对S0→S1 Dice表观变化含有效队列改变，不能解释成排除策略收益：GLaS从4张变1张，CRAG从13张变10张；对应共同有效队列的实际变化只有约0.00036/0.00033。\n\nS0的参考来自同一图，已入Memory的位置可能直接检索到自身，最大cosine可为1；S1排除该空间证据。如果S1降低有效率，说明邻域外证据不足；只有共同有效的变化才支持讨论自匹配对Dice/AUROC的影响。它仍不是跨图泛化检验。','','## 6. Unseeded Gland Recovery','',md(exp),'', 'Known-FG、Known-BG、Ignore独立分区（256上NN映射，三值互斥保留），重点看Ignore中的FG recall与BG specificity，并同时看AUROC。原Seed未命中GT对象中，预测覆盖该GT对象面积>0.5称为恢复；此定义不要求预测实例一对一匹配，必须结合Object-F1和BG specificity防止全FG假恢复。无有效Memory的图恢复率为N/A，不按0伪装或从全体分母中隐去。可执行率始终另外报告。','','## 7. Failure Modes','']
    for ds in ['GlaS','CRAG']:
        sub=p[p.dataset==ds]
        for g in ['A','B','C']:
            q=sub[sub.generator==g];wrongfg=int((q.fg_seed_pixels-q.fg_correct_pixels).sum());wrongbg=int((q.bg_seed_pixels-q.bg_correct_pixels).sum());missing=int((q.gt_objects_256-q.seeded_objects_256).sum())
            lines += [f'{ds}/{g}: 已确认错误FG Seed像素={wrongfg}，错误BG Seed像素={wrongbg}；256上无FG Seed命中的GT对象={missing}。后两者分别说明BG污染和missing proposal/coverage；仅依据这些计数不能把具体错误归因于腔、炎症或染色异常。','']
    gates=gate.groupby(['dataset','branch','rule'],as_index=False)[['input_pixels','accepted_pixels','rejected_pixels']].sum()
    lines += ['固定外观、上皮/内部及正向BG规则的图像-only拒绝计数可定位候选在各门控的损失，未改变原规则：','',md(gates),'', 'hole规则各步输入/拒绝面积在morphology_rule_rejections.csv。Lumen/tissue gap confusion由RGB/候选/GT叠图及candidate GT比例作诊断；光度candidate可能混合不同结构，不能用其总错误率认定特定解剖误差。Token spatial mixing可由像素Seed非空但16×16严格候选减少，以及GT purity变化定位；这不是坐标错位，窗口/reflection对齐测试和cache位置验证已通过。Self-matching leakage仅在S0/S1共同有效对照和有效率的实际差异支持范围内讨论，不预设其一定造成高Dice。','', '## 8. Final Conclusion','']
    for ds in ['GlaS','CRAG']:
        ss=s[s.dataset==ds].set_index('generator');tt=t[t.dataset==ds].set_index('generator')
        lines += [f'{ds}: A/B/C的Macro FG precision分别为 '+', '.join('N/A' if pd.isna(ss.loc[g,'macro_fg_precision']) else f"{ss.loc[g,'macro_fg_precision']:.4f}" for g in ['A','B','C'])+'；FG coverage分别 '+', '.join(f"{ss.loc[g,'macro_fg_coverage']:.4f}" for g in ['A','B','C'])+'；E2基础Memory有效率分别 '+', '.join(f"{tt.loc[g,'valid_rate']:.1%}" for g in ['A','B','C'])+'。这些是完整80/40张分母，不是只挑有Seed图。','']
    allvalid=int(t.valid_memories.sum());total=int(t.images.sum());lines += [f'能否生成可靠三值Seeds：存在局部非空候选，但需以表中GT precision与coverage共同判断，不能由三值格式合法推出语义可靠。数量上仅{allvalid}/{total}个图像×generator条件满足两类Top50，说明在当前固定规则下并没有普遍可用的Self-reference Memory。', '', 'A/B/C的取舍必须区分像素精度和可用性：B/C更严格不保证经验精度一定更高，C的类别交集可能将BG或FG完全过滤；它不能靠只保留更少像素就被宣布更合理。实际选择不反馈给推理，不把报告中的事后比较当成GT无关的自动方法。', '', '少量Seeds能否恢复未覆盖腺体：仅能在Ignore区域表和未seed对象恢复表的有效子集上观察；同时受BG污染/低覆盖及自匹配影响，不支持将局部成功外推为完整数据集可用。当前E0/E1的空类和覆盖不足发生在检索之前，主要瓶颈首先是可靠的两类Seed生成，严格Token映射进一步减少可用参考；没有证据表明放宽K或加入MAP/Local Prototype可从无类证据恢复语义。', '', '**后续仅一项实验：Morphology/正向基质证据门控的单因素诊断。** 固定FG与检索链路，只比较当前BG邻接一致性门控保留/移除的预先登记对照，仍禁止NOT FG，并在独立诊断图像上同时报告BG precision、coverage与两类Token可用率。理由是本次BG门控拒绝与空Memory有直接中间量证据；不实施新Prototype或MAP，也不声称该改变必然提高质量。','', '**证据边界：**观察到的错误像素、空类、数量不足、对象漏种及配对指标为Confirmed；某种组织/炎症形态造成特定失败、腔解剖身份及跨患者泛化为未验证假设。当前报告不宣称training-free self-reference成功。']
    # Replace generic closing remarks with explicit judgments supported by the completed fixed experiment.
    last=lines.index('## 8. Final Conclusion')
    lines[last+1:]=[
        '', '1. **无GT能否可靠地产生Seeds？** 本版不能在两个完整测试集上稳定产生可靠的两类Seeds。A的Macro FG precision仅GLaS 0.6350、CRAG 0.6683，FG覆盖分别0.1505/0.3117；B/C并未普遍解决误标，同时BG几乎或完全消失。局部高精度例存在（如GLaS test_a_testA_12的A FG precision0.963、BG0.998），不能外推到全体。', '',
        '2. **哪种precision/coverage取舍合理？** 没有一组在本次两类Memory目标上达标。A是唯一有实际可执行子集的基线，但错误FG/BG较多；B/C适合作为收缩候选的诊断，不能被选为可用的双类Self-reference方案。C的Macro FG precision在CRAG升至0.8273、但GLaS降至0.6015，说明稳定性不等价于语义正确；C在CRAG pooled precision0.7210，与A的0.7192几乎相同，而pooled FG coverage由0.2888跌至0.0051。', '',
        '3. **Token是否足够且可靠？** A只有GLaS4/80、CRAG13/40张两类≥50；B/C均0。C严格FG候选在GLaS共有752条、GT平均纯度0.99734，CRAG仅6条、纯度1，但BG均0。物理位置重复后，C的FG参考仅GLaS290个唯一center、CRAG2个，跨多图统计也不能合并为某张图可用Memory。稀少正确FG Token是局部正面信号，但不足以支持双类检索。Epithelial分支的严格候选极少：GLaS B/C均0，CRAG B仅4、C为0；绝大多数严格FG来自interior，表明薄带与Ignore在16×16网格上的混合是实际约束。', '',
        '4. **能否恢复未覆盖腺体？** A在可执行S0子集上，GLaS未seed对象8/8、CRAG46/46被预测覆盖>50%，但Ignore BG specificity仅0.4854/0.3979；predicted FG ratio均值0.8198/0.7623，Object-F1仅0.4306/0.3112。高恢复计数伴随大量BG误报，不能单独证明可靠语义扩展。对共同有效子集重新分母对齐的Ignore分析见paired_ignore_expansion.csv；B/C无可执行检索，恢复指标必须N/A。', '',
        '5. **瓶颈在哪里？** 首先是Seed Generation：错误FG proposal和正向BG的不足在检索前已经存在。B的邻接门控把GLaS剩余20813个BG候选像素全部删除，把CRAG173354个删除到1264个，腐蚀后仅1014个（1张图、16个Token，仍不足K）。这是门控拒绝的直接中间量证据，不代表移除它一定能保持精度。严格Token Mapping随后进一步压缩覆盖，窗口坐标本身的正确性检查通过。S1共同有效图的Dice变化仅GLaS +0.000360（n=1）、CRAG +0.000335（n=10），Object-F1不变；当前没有观察到大的自匹配虚高效应，但不能据这些小/选择后的子集排除其他图的自匹配影响。', '',
        '6. **下一项只选Morphology/正向基质证据门控。** 固定B的FG和检索链路，仅做BG邻接一致性门控保留/移除的预先登记单因素对照，并在独立诊断图上同时评价BG precision、coverage及两类Token可用率；保持正向组织证据，禁止NOT FG。此次不实施该后续实验。先改善可靠双类证据才有理由讨论Local Prototype、MAP或Reliable Retrieval，当前结果不证明这些模块能补救空类。', '',
        '**Confirmed：**错误像素、空类、数量不足、门控拒绝、漏种及配对指标。**Unverified：**具体炎症/染色成因、候选腔的解剖身份、后续门控消融是否改善精度、跨患者泛化。结论只适用于这套预先固定的heuristic，不能否定所有无训练Self-reference方法；本次不宣称方法成功。']
    ins=lines.index('## 4. Token-level Reliability')
    lines[ins:ins]=['定性GT核对：固定样例GLaS test_a_testA_1/test_a_testA_46的部分亮内部区域位于GT腺体范围内，但test_b_testB_9可见环形范围内的GT孔洞；CRAG的外部白背景也未被整体标成腺体。因此“所有亮洞/填充都是FG”不成立。当前RGB lumen候选落在GT FG内的pooled比例为GLaS0.8125、CRAG0.6030，证明候选混有非FG区域，不能当作真实lumen标注。','']
    ins=lines.index('## 6. Unseeded Gland Recovery')
    physical=pd.read_csv(OUT/'physical_reference_diversity.csv').groupby(['dataset','generator'],as_index=False)[['fg_memory_tokens','fg_unique_physical_centers','bg_memory_tokens','bg_unique_physical_centers']].sum()
    lines[ins:ins]=['参考位置去重计数（各图先去重再求和；不是不同图之间共享Memory）：','',md(physical),'']
    matched=pd.read_csv(OUT/'paired_ignore_expansion.csv')
    ins=lines.index('## 7. Failure Modes')
    lines[ins:ins]=['S0/S1相同有效图像的Ignore区域对照：','',md(matched),'', '可视化为完整native图；256 Margin/Mask单独标尺度，margin色条固定显示[-0.25,0.25]，原始未裁剪数组已保存。14例展示选择在全统计完成后事后确定，选择规则和ID在visualization_selection.csv，未用于选择参数或修改预测。','']
    (OUT/'report.md').write_text('\n'.join(lines)+'\n')
    # Preserve all statuses and exact executed configuration/code references.
    assert len(p)==360 and len(f)==360
    raw=pd.read_csv(OUT/'self_reference_per_image.csv');assert len(raw)==720
    assert raw.top_k.eq(50).all();assert f.top_k.eq(50).all()
    cache=pd.read_csv(OUT/'query_cache_validation.csv');assert len(cache)==240
    assert '12 passed' in (OUT/'tests.log').read_text()
    source=[*sorted((ROOT/'scripts').glob('*self_reference*.py')),*sorted((ROOT/'pathology_trainfree/self_reference').glob('*.py')),ROOT/'tests/test_self_reference.py',ROOT/'configs/self_reference_e0.yaml']
    required=['seed_metrics_per_image.csv','seed_summary.csv','object_seed_coverage.csv','token_reliability.csv','memory_feasibility.csv','self_reference_per_image.csv','self_reference_summary.csv','seed_expansion_metrics.csv','failure_cases.csv','report.md','execution.log']
    assert all((OUT/x).exists() for x in required)
